using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.DependencyInjection; using SmartERP.Sales.DataAccess.Contexts; using SmartERP.Sales.DataAccess.Repositories; using SmartERP.Sales.Repositories.Interfaces;
namespace SmartERP.Sales.DataAccess;
public static class DependencyInjection { public static IServiceCollection AddSalesDataAccess(this IServiceCollection s,IConfiguration c) { var connection=c.GetConnectionString("SalesDatabase")??throw new InvalidOperationException("Connection string 'SalesDatabase' was not found.");s.AddDbContext<SalesDbContext>(o=>o.UseSqlServer(connection,sql=>{sql.MigrationsAssembly(typeof(SalesDbContext).Assembly.FullName);sql.EnableRetryOnFailure(5,TimeSpan.FromSeconds(10),null);}));s.AddScoped<ISalesFinancialRecordRepository,SalesFinancialRecordRepository>();return s;} }
